// MODE: defend (hold rally, leash) | attack (push to TGT)
const MODE = "defend";
const RALLY = {x:7,y:7};
const TGT = {x:27,y:27};
const LEASH = 7;
const PRI = {knight:0, worker:1, agent:2, turret:3, nexus:4, wall:5};
function pick(list, agentFirst){
  let best=null, bs=1e9;
  for (const u of list){
    let p = PRI[u.type] ?? 6;
    if (agentFirst && u.type==="agent") p = -1;
    const s = p*1000 + u.hp;
    if (s<bs){bs=s;best=u;}
  }
  return best;
}
const near = self.nearbyEnemies();
const hasKnights = near.some(u=>u.type==="knight");
const inR = self.enemiesInRange();
if (MODE === "attack") {
  if (inR.length) { self.attack(pick(inR, !hasKnights)); }
  else if (near.length) { self.attack(pick(near, !hasKnights)); }
  else if (self.distanceToPos(TGT.x,TGT.y) > 1) self.moveTo(TGT.x, TGT.y);
  else self.hold();
} else {
  const dr = self.distanceToPos(RALLY.x, RALLY.y);
  if (inR.length && dr <= LEASH+2) { self.attack(pick(inR, !hasKnights)); }
  else if (near.length && dr <= LEASH) {
    const t = pick(near, !hasKnights);
    if (self.distanceToPos(t.x,t.y) <= LEASH+3) self.attack(t); else self.moveTo(RALLY.x, RALLY.y);
  }
  else if (dr > 1) self.moveTo(RALLY.x, RALLY.y);
  else self.hold();
}

